import 'package:flutter/material.dart';
import '../../enums/enums.dart';

const navy = Color(0xFF0B1736); const blue = Color(0xFF2D6CDF); const mint = Color(0xFF20B486); const ink = Color(0xFF172033); const muted = Color(0xFF6C7487); const surface = Color(0xFFF5F7FB);

class StatusPill extends StatelessWidget { final String label; final Color color; const StatusPill(this.label,{required this.color,super.key}); @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:color.withOpacity(.1),borderRadius:BorderRadius.circular(20)),child:Text(label,style:TextStyle(color:color,fontSize:12,fontWeight:FontWeight.w700))); }
class MetricCard extends StatelessWidget { final String label,value; final IconData icon; final Color color; const MetricCard({required this.label,required this.value,required this.icon,required this.color,super.key}); @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFFE8ECF4))),child:Row(children:[Container(width:44,height:44,decoration:BoxDecoration(color:color.withOpacity(.12),borderRadius:BorderRadius.circular(12)),child:Icon(icon,color:color)),const SizedBox(width:14),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800,color:ink)),Text(label,style:const TextStyle(color:muted,fontSize:12))])]); }
Color remarkColor(GradeRemark remark)=>switch(remark){GradeRemark.passed=>mint,GradeRemark.failed=>const Color(0xFFE45454),GradeRemark.incomplete=>const Color(0xFFF2A93B),GradeRemark.dropped=>const Color(0xFF8A91A3),GradeRemark.withdrawn=>const Color(0xFF8A91A3)};
